begin;

update public.pooja_steps set instruction_ta = 'தேவியை ஆவாஹனம் செய்வதற்கு முன், ஒன்பது முடிச்சுகள் கொண்ட நோன்பு சரடை சமர்ப்பணப் பொருட்களுடன் வைத்து, இந்த மந்திரத்தால் அதை ஆவாஹனம் செய்யவும். பூஜை முழுவதும் சரடு அங்கேயே இருக்கும்; இறுதியில் ஒவ்வொரு முடிச்சாகப் பூஜிக்கப்படும்.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dora Sthapanam'
   and coalesce(trim(instruction_ta), '') = '';

update public.pooja_steps set instruction_ta = 'மலர்களும் அக்ஷதையும் சமர்ப்பித்து, கலசத்தில் தேவியை ஆவாஹனம் செய்யவும்.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Avahanam'
   and coalesce(trim(instruction_ta), '') = '';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- No step in either pooja may have an English instruction and no Tamil one.
  select count(*) into n from public.pooja_steps
   where coalesce(trim(instruction_en), '') <> ''
     and coalesce(trim(instruction_ta), '') = '';
  if n > 0 then raise exception '% steps have an English instruction and no Tamil', n; end if;

  -- And the Tamil is Tamil, not Devanagari that leaked across.
  select count(*) into n from public.pooja_steps
   where instruction_ta ~ '[\u0900-\u097F]';
  if n > 0 then raise exception '% instruction_ta carry Devanagari', n; end if;
end $$;


